/// The block's mineable tool class (the None the undemanding block
/// the default rule rides).
pub fn mineable_class(name: &str) -> Option<u8> {
    let pos = MINEABLE_SORTED
        .binary_search_by(|probe| MINEABLE_NAMES[*probe as usize].cmp(name))
        .ok()? as usize;
    Some(MINEABLE_CLASS[MINEABLE_SORTED[pos] as usize])
}
